class Solution:
    def findMaxConsecutiveOnes(self, nums: List[int]) -> int:
        best = run = 0
        for x in nums:
            if x == 1:
                run += 1
                best = max(best, run)   # update inside the run so a trailing run counts
            else:
                run = 0                 # a 0 breaks every run that crosses it
        return best

class Solution:
    def maxProduct(self, nums: List[int]) -> int:
        hi = lo = best = nums[0]
        for x in nums[1:]:
            # a negative x turns the smallest product into the largest, so carry both
            cands = (x, hi * x, lo * x)
            hi, lo = max(cands), min(cands)
            best = max(best, hi)
        return best

