class Solution:
    def getIntersectionNode(self, headA: ListNode, headB: ListNode) -> Optional[ListNode]:
        def length(node: Optional[ListNode]) -> int:
            count = 0
            while node:
                count, node = count + 1, node.next
            return count

        m, n = length(headA), length(headB)
        a, b = headA, headB
        for _ in range(m - n):        # skip the longer private prefix
            a = a.next
        for _ in range(n - m):
            b = b.next
        while a is not b:             # equal distance to the end now: lockstep walk
            a, b = a.next, b.next
        return a

class Solution:
    def hasCycle(self, head: Optional[ListNode]) -> bool:
        slow = fast = head
        while fast and fast.next:
            slow, fast = slow.next, fast.next.next
            if slow is fast:          # fast lapped slow inside the loop
                return True
        return False

