class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        slow = fast = 0
        while True:                      # phase 1: meet somewhere inside the cycle
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        slow = 0                         # phase 2: head and meeting point converge on entrance
        while slow != fast:
            slow, fast = nums[slow], nums[fast]
        return slow

