def brute_force(nums: List[int]) -> List[int]:
    n = len(nums)
    ans = [-1] * n
    for i in range(n):
        for k in range(1, n):                 # re-walks the circle from every index
            if nums[(i + k) % n] > nums[i]:
                ans[i] = nums[(i + k) % n]
                break
    return ans

