class Solution:
    def minAddToMakeValid(self, s: str) -> int:
        open_ = 0          # unmatched '(' so far (height of the would-be stack)
        adds = 0           # ')' that had nothing to match: each needs an inserted '('
        for c in s:
            if c == "(":
                open_ += 1
            elif open_ > 0:
                open_ -= 1
            else:
                adds += 1
        return adds + open_

