class Solution:
    def searchInsert(self, nums: List[int], target: int) -> int:
        lo, hi = 0, len(nums) - 1
        ans = len(nums)                  # if nothing is >= target, insert at the end
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] >= target:      # mid is a candidate; look for an earlier one
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

