def brute_force(position: List[int], m: int) -> int:
    pos = sorted(position)
    best = 1
    for d in range(1, pos[-1] - pos[0] + 1):   # tries every gap, one at a time
        count, last = 1, pos[0]
        for p in pos[1:]:
            if p - last >= d:
                count, last = count + 1, p
        if count >= m:
            best = d
    return best

