class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        ans: List[List[int]] = []
        path: List[int] = []

        def dfs(node: Optional[TreeNode], remaining: int) -> None:
            if node is None:
                return
            path.append(node.val)
            remaining -= node.val
            if node.left is None and node.right is None:
                if remaining == 0:
                    ans.append(path[:])          # snapshot; path keeps mutating
            else:
                dfs(node.left, remaining)
                dfs(node.right, remaining)
            path.pop()                           # backtrack so siblings see the right prefix

        dfs(root, targetSum)
        return ans

class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        def mirror(a: Optional[TreeNode], b: Optional[TreeNode]) -> bool:
            if a is None or b is None:
                return a is b                     # both missing -> mirror; one missing -> not
            return (a.val == b.val
                    and mirror(a.left, b.right)   # outer pair
                    and mirror(a.right, b.left))  # inner pair

        return root is None or mirror(root.left, root.right)

